        let released = ready_bits & RELEASED == RELEASED;
        let tx_closed = ready_bits & TX_CLOSED == TX_CLOSED;
        let block_start = self.header.start_index;
        let block_end = block_start.wrapping_add(BLOCK_CAP);
        let aligned_index = start_index(slot_index);
        let wrapped_offset = offset(slot_index);
        let same_block = self.is_at_index(aligned_index);
        let block_distance = self.distance(aligned_index);
        let in_block_offset = slot_index.wrapping_sub(block_start);
        let spans_next_block = aligned_index == block_end;
