        let mut last_ready = 0usize;
        let mut low_ready = 0usize;
        let mut high_ready = 0usize;
        let mut even_ready = 0usize;
        let mut odd_ready = 0usize;
        let mut rebuilt_bits = 0usize;
        let mut bit_index = 0usize;
        while bit_index < BLOCK_CAP {
